sealed interface UiState {
    data object Loading : UiState                       // prints as "Loading"
    data class Content(val items: List<String>) : UiState
    data class Error(val message: String) : UiState
}

println(UiState.Loading)   // Loading   (a plain object would print an address-like name)

sealed interface Payment { data object Card : Payment; data object Cash : Payment; data object Wallet : Payment }

fun fee(p: Payment): Int = when (p) {
    Payment.Card -> 3
    Payment.Cash -> 0
    Payment.Wallet -> 1
    // no else: adding a new Payment breaks the build here, which is the point
}

// Impossible states are representable:
data class ScreenState(val isLoading: Boolean, val error: String?, val items: List<Item>?)

// Only valid states exist:
sealed interface Screen {
    data object Loading : Screen
    data class Loaded(val items: List<Item>) : Screen
    data class Failed(val message: String) : Screen
}

@Composable fun Render(s: Screen) = when (s) {
    Screen.Loading -> Spinner()
    is Screen.Loaded -> List(s.items)
    is Screen.Failed -> ErrorText(s.message)
}
